params.command:
$ErrorActionPreference='Stop'
$root=Join-Path $env:USERPROFILE 'HeavenBridgeRepo'
git -C $root fetch --quiet origin main
$tmp=Join-Path $env:TEMP 'mhw-hcp-runner-v2-recover'
if(Test-Path $tmp){ git -C $root worktree remove --force $tmp 2>$null; Remove-Item -Recurse -Force $tmp -ErrorAction SilentlyContinue }
$sha=(git -C $root rev-parse origin/main).Trim()
git -C $root worktree add --detach $tmp $sha | Out-Null
try {
  & (Join-Path $tmp 'heaven-bridge\install-github-runner.ps1') -RunnerName 'heaven-v2' -RunnerDirectory (Join-Path $env:USERPROFILE 'actions-runner-heaven-v2') -Labels @('heaven-v2','local-bridge','mhw-mods')
  if($LASTEXITCODE -ne 0){ throw ('runner installer failed: '+$LASTEXITCODE) }
  Write-Output ('RUNNER_RECOVERY_SHA='+$sha)
} finally { git -C $root worktree remove --force $tmp 2>$null; Remove-Item -Recurse -Force $tmp -ErrorAction SilentlyContinue }
